
import 'package:flutter/material.dart';
import 'package:sqflite/sqflite.dart';
import 'package:path/path.dart';
import 'package:intl/intl.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';

const blue=Color(0xFF1677D2), navy=Color(0xFF102A43);
String money(num n)=>NumberFormat('#,##0','fa').format(n);
late Database db;
Future<void> main() async {
 WidgetsFlutterBinding.ensureInitialized();
 db=await openDatabase(join(await getDatabasesPath(),'pars_acc.db'),version:1,onCreate:(d,v) async {
  await d.execute('CREATE TABLE products(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,sku TEXT,unit TEXT,buy REAL,sell REAL,qty REAL,minqty REAL)');
  await d.execute('CREATE TABLE invoices(id INTEGER PRIMARY KEY AUTOINCREMENT,no TEXT,customer TEXT,phone TEXT,date TEXT,total REAL,paid REAL,note TEXT)');
  await d.execute('CREATE TABLE lines(id INTEGER PRIMARY KEY AUTOINCREMENT,invoice_id INTEGER,title TEXT,qty REAL,price REAL,sum REAL)');
  await d.execute('CREATE TABLE cash(id INTEGER PRIMARY KEY AUTOINCREMENT,type TEXT,title TEXT,amount REAL,date TEXT,note TEXT)');
 });
 runApp(const App());
}
class App extends StatelessWidget {const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'حسابداری پارس',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:blue),scaffoldBackgroundColor:const Color(0xfff2f6fa)),home:const Directionality(textDirection:TextDirection.rtl,child:Shell()));}
class Shell extends StatefulWidget{const Shell({super.key});@override State<Shell> createState()=>_ShellState();}
class _ShellState extends State<Shell>{int tab=0;final pages=[const Home(),const Stock(),const Bills(),const Cash(),const Reports()];final names=['خانه','انبار','فاکتور','مالی','گزارش'];final icons=[Icons.dashboard,Icons.inventory_2,Icons.receipt_long,Icons.account_balance_wallet,Icons.analytics];@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(backgroundColor:navy,foregroundColor:Colors.white,centerTitle:true,title:const Column(children:[Text('حسابداری پارس',style:TextStyle(fontWeight:FontWeight.bold)),Text('سیستم‌های حفاظتی پارس • امنیت، آرامش، اعتماد',style:TextStyle(fontSize:10))])),body:pages[tab],bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:List.generate(5,(i)=>NavigationDestination(icon:Icon(icons[i]),label:names[i]))));}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{Map<String,num>s={};List<Map<String,Object?>> low=[];Future<void> load()async{final p=await db.rawQuery('SELECT COUNT(*) c,COALESCE(SUM(qty*buy),0) val FROM products');final i=await db.rawQuery("SELECT COALESCE(SUM(total),0) v,COALESCE(SUM(total-paid),0) due FROM invoices");final cash=await db.rawQuery("SELECT type,COALESCE(SUM(amount),0) v FROM cash GROUP BY type");final stock=await db.query('products');num income=0,expense=0;for(final x in cash){if(x['type']=='in')income=x['v'] as num;else expense=x['v'] as num;}if(!mounted)return;setState((){s={'count':p.first['c'] as num,'stock':p.first['val'] as num,'sales':i.first['v'] as num,'due':i.first['due'] as num,'income':income,'expense':expense};low=stock.where((x)=>(x['qty'] as num)<=(x['minqty'] as num)).toList();});}
@override void initState(){super.initState();load();}
@override Widget build(BuildContext c)=>RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(15),children:[Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(gradient:const LinearGradient(colors:[navy,blue]),borderRadius:BorderRadius.circular(20)),child:const Text('مدیریت مالی و انبار پارس\\nامنیت، آرامش، اعتماد',style:TextStyle(color:Colors.white,fontSize:20,fontWeight:FontWeight.bold))),const SizedBox(height:14),GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:2,childAspectRatio:1.6,children:[stat('تعداد کالا',s['count']??0,'عدد'),stat('ارزش موجودی',s['stock']??0,'تومان'),stat('مجموع فاکتورها',s['sales']??0,'تومان'),stat('مانده مشتریان',s['due']??0,'تومان'),stat('دریافت‌ها',s['income']??0,'تومان'),stat('هزینه‌ها',s['expense']??0,'تومان')]),const SizedBox(height:12),const Text('هشدار کمبود موجودی',style:TextStyle(fontSize:17,fontWeight:FontWeight.bold)),if(low.isEmpty)const Card(child:ListTile(title:Text('موردی برای هشدار وجود ندارد'),leading:Icon(Icons.check_circle,color:Colors.green))) else ...low.map((x)=>Card(child:ListTile(title:Text(x['name'].toString()),subtitle:Text('موجودی: ${money(x['qty'] as num)} ${x['unit']}'),leading:const Icon(Icons.warning,color:Colors.orange))))]));}
Widget stat(String t,num v,String u)=>Card(child:Padding(padding:const EdgeInsets.all(10),child:Column(mainAxisAlignment:MainAxisAlignment.center,crossAxisAlignment:CrossAxisAlignment.start,children:[Text(t,style:const TextStyle(color:Colors.grey)),FittedBox(child:Text(money(v),style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold,color:blue))),Text(u,style:const TextStyle(fontSize:10))])));
class Stock extends StatefulWidget{const Stock({super.key});@override State<Stock> createState()=>_StockState();}
class _StockState extends State<Stock>{List<Map<String,Object?>> data=[];Future<void> load()async{final x=await db.query('products',orderBy:'name');if(mounted)setState(()=>data=x);} @override void initState(){super.initState();load();}
Future<void> edit([Map<String,Object?>? p])async{final ctrls=[TextEditingController(text:p?['name']?.toString()??''),TextEditingController(text:p?['sku']?.toString()??''),TextEditingController(text:p?['unit']?.toString()??'عدد'),TextEditingController(text:p?['buy']?.toString()??'0'),TextEditingController(text:p?['sell']?.toString()??'0'),TextEditingController(text:p?['qty']?.toString()??'0'),TextEditingController(text:p?['minqty']?.toString()??'0')];final labels=['نام کالا','کد کالا','واحد','قیمت خرید (تومان)','قیمت فروش (تومان)','موجودی','حداقل موجودی'];final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(p==null?'افزودن کالا':'ویرایش کالا'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:List.generate(7,(i)=>Padding(padding:const EdgeInsets.only(bottom:8),child:TextField(controller:ctrls[i],keyboardType:i>2?const TextInputType.numberWithOptions(decimal:true):TextInputType.text,decoration:InputDecoration(labelText:labels[i],border:const OutlineInputBorder()))))),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('انصراف')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('ذخیره'))]));if(ok==true&&ctrls[0].text.trim().isNotEmpty){final row={'name':ctrls[0].text,'sku':ctrls[1].text,'unit':ctrls[2].text,'buy':double.tryParse(ctrls[3].text)??0,'sell':double.tryParse(ctrls[4].text)??0,'qty':double.tryParse(ctrls[5].text)??0,'minqty':double.tryParse(ctrls[6].text)??0};if(p==null){await db.insert('products',row);}else{await db.update('products',row,where:'id=?',whereArgs:[p['id']]);}await load();}}
@override Widget build(BuildContext c)=>Column(children:[Padding(padding:const EdgeInsets.all(12),child:Row(children:[const Expanded(child:Text('کالاها و موجودی انبار',style:TextStyle(fontWeight:FontWeight.bold,fontSize:17)),),FilledButton.icon(onPressed:()=>edit(),icon:const Icon(Icons.add),label:const Text('افزودن'))])),Expanded(child:data.isEmpty?const Center(child:Text('هنوز کالایی ثبت نشده است')):ListView(children:data.map((p)=>Card(child:ListTile(title:Text(p['name'].toString()),subtitle:Text('موجودی ${money(p['qty'] as num)} ${p['unit']} | فروش ${money(p['sell'] as num)} تومان'),leading:const Icon(Icons.inventory_2,color:blue),trailing:PopupMenuButton<String>(onSelected:(v)async{if(v=='e')await edit(p);if(v=='d'){await db.delete('products',where:'id=?',whereArgs:[p['id']]);await load();}},itemBuilder:(_)=>const [PopupMenuItem(value:'e',child:Text('ویرایش')),PopupMenuItem(value:'d',child:Text('حذف'))]))).toList()))]);}}
class Bills extends StatefulWidget{const Bills({super.key});@override State<Bills> createState()=>_BillsState();}
class _BillsState extends State<Bills>{List<Map<String,Object?>> data=[];Future<void>load()async{final x=await db.query('invoices',orderBy:'id DESC');if(mounted)setState(()=>data=x);}@override void initState(){super.initState();load();}
Future<void> add()async{final products=await db.query('products');if(products.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ابتدا کالا در انبار ثبت کنید')));return;}final customer=TextEditingController(),phone=TextEditingController(),paid=TextEditingController(text:'0');int? chosen=products.first['id'] as int;final qty=TextEditingController(text:'1');final price=TextEditingController(text:products.first['sell'].toString());final selected=<Map<String,Object?>>[];final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setD)=>AlertDialog(title:const Text('فاکتور فروش جدید'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:customer,decoration:const InputDecoration(labelText:'نام مشتری')),TextField(controller:phone,decoration:const InputDecoration(labelText:'شماره تماس')),DropdownButtonFormField<int>(value:chosen,items:products.map((p)=>DropdownMenuItem(value:p['id'] as int,child:Text(p['name'].toString()))).toList(),onChanged:(v){setD((){chosen=v;final p=products.firstWhere((x)=>x['id']==v);price.text=p['sell'].toString();});},decoration:const InputDecoration(labelText:'کالا')),TextField(controller:qty,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'تعداد')),TextField(controller:price,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'قیمت واحد')),OutlinedButton(onPressed:(){final p=products.firstWhere((x)=>x['id']==chosen);final q=double.tryParse(qty.text)??0;if(q<=0)return;selected.add({'name':p['name'],'qty':q,'price':double.tryParse(price.text)??0,'pid':chosen});qty.text='1';setD((){});},child:Text('افزودن ردیف (${selected.length})')),Text('جمع: ${money(selected.fold<num>(0,(s,x)=>s+(x['qty'] as num)*(x['price'] as num)))} تومان'),TextField(controller:paid,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'مبلغ دریافتی'))])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('لغو')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('ثبت فاکتور'))])));if(ok!=true||customer.text.trim().isEmpty||selected.isEmpty)return;final total=selected.fold<double>(0,(s,x)=>s+(x['qty'] as num)*(x['price'] as num));final received=double.tryParse(paid.text)??0;if(received>total){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('دریافتی از مبلغ فاکتور بیشتر است')));return;}await db.transaction((t)async{final no='P-${DateTime.now().millisecondsSinceEpoch.toString().substring(7)}';final id=await t.insert('invoices',{'no':no,'customer':customer.text,'phone':phone.text,'date':DateTime.now().toIso8601String(),'total':total,'paid':received,'note':''});for(final x in selected){await t.insert('lines',{'invoice_id':id,'title':x['name'],'qty':x['qty'],'price':x['price'],'sum':(x['qty'] as num)*(x['price'] as num)});await t.rawUpdate('UPDATE products SET qty=qty-? WHERE id=?',[x['qty'],x['pid']]);}if(received>0)await t.insert('cash',{'type':'in','title':'دریافت فاکتور $no','amount':received,'date':DateTime.now().toIso8601String(),'note':''});});await load();}
Future<void> pdf(Map<String,Object?> inv)async{final lines=await db.query('lines',where:'invoice_id=?',whereArgs:[inv['id']]);final doc=pw.Document();doc.addPage(pw.Page(build:(c)=>pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.start,children:[pw.Text('PARS SECURITY SYSTEMS',style:pw.TextStyle(fontSize:18,fontWeight:pw.FontWeight.bold)),pw.SizedBox(height:12),pw.Text('Invoice ${inv['no']}'),pw.Text('Customer: ${inv['customer']}'),pw.Text('Phone: ${inv['phone']}'),pw.Divider(),...lines.map((x)=>pw.Text('${x['title']} | ${x['qty']} x ${x['price']} = ${x['sum']}')),pw.Divider(),pw.Text('Total: ${inv['total']} Toman'),pw.Text('Paid: ${inv['paid']} Toman'),pw.Text('Due: ${(inv['total'] as num)-(inv['paid'] as num)} Toman')])));await Printing.layoutPdf(onLayout:(_)=>doc.save());}
@override Widget build(BuildContext c)=>Column(children:[Padding(padding:const EdgeInsets.all(12),child:SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:add,icon:const Icon(Icons.add),label:const Text('صدور فاکتور فروش')))),Expanded(child:data.isEmpty?const Center(child:Text('فاکتوری ثبت نشده')):ListView(children:data.map((x)=>Card(child:ListTile(title:Text('${x['no']} • ${x['customer']}'),subtitle:Text('مبلغ ${money(x['total'] as num)} | مانده ${money((x['total'] as num)-(x['paid'] as num))} تومان'),leading:const Icon(Icons.receipt,color:blue),trailing:IconButton(onPressed:()=>pdf(x),icon:const Icon(Icons.picture_as_pdf))))).toList()))]);}}
class Cash extends StatefulWidget{const Cash({super.key});@override State<Cash> createState()=>_CashState();}
class _CashState extends State<Cash>{List<Map<String,Object?>> rows=[];Future<void>load()async{final x=await db.query('cash',orderBy:'id DESC');if(mounted)setState(()=>rows=x);}@override void initState(){super.initState();load();}
Future<void> add()async{String type='out';final title=TextEditingController(),amount=TextEditingController(),note=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setD)=>AlertDialog(title:const Text('ثبت دریافت یا هزینه'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField(value:type,items:const [DropdownMenuItem(value:'in',child:Text('دریافت')),DropdownMenuItem(value:'out',child:Text('پرداخت / هزینه'))],onChanged:(v)=>setD(()=>type=v!),decoration:const InputDecoration(labelText:'نوع')),TextField(controller:title,decoration:const InputDecoration(labelText:'عنوان')),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'مبلغ تومان')),TextField(controller:note,decoration:const InputDecoration(labelText:'توضیحات'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('لغو')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('ثبت'))])));if(ok==true&&title.text.isNotEmpty&&(double.tryParse(amount.text)??0)>0){await db.insert('cash',{'type':type,'title':title.text,'amount':double.parse(amount.text),'date':DateTime.now().toIso8601String(),'note':note.text});await load();}}
@override Widget build(BuildContext c)=>Column(children:[Padding(padding:const EdgeInsets.all(12),child:SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:add,icon:const Icon(Icons.add),label:const Text('ثبت دریافت / هزینه')))),Expanded(child:ListView(children:rows.map((x)=>Card(child:ListTile(title:Text(x['title'].toString()),subtitle:Text(x['type']=='in'?'دریافت':'پرداخت'),leading:Icon(x['type']=='in'?Icons.south_west:Icons.north_east,color:x['type']=='in'?Colors.green:Colors.red),trailing:Text('${money(x['amount'] as num)} تومان')))).toList()))]);}}
class Reports extends StatefulWidget{const Reports({super.key});@override State<Reports> createState()=>_ReportsState();}
class _ReportsState extends State<Reports>{Map<String,num> v={};Future<void>load()async{final p=await db.rawQuery('SELECT COALESCE(SUM(qty*buy),0) v FROM products');final i=await db.rawQuery('SELECT COALESCE(SUM(total),0) s,COALESCE(SUM(total-paid),0) d FROM invoices');final c=await db.rawQuery("SELECT type,COALESCE(SUM(amount),0) v FROM cash GROUP BY type");num income=0,expense=0;for(final x in c){if(x['type']=='in')income=x['v'] as num;else expense=x['v'] as num;}if(mounted)setState(()=>v={'stock':p.first['v'] as num,'sales':i.first['s'] as num,'due':i.first['d'] as num,'income':income,'expense':expense});}@override void initState(){super.initState();load();}
@override Widget build(BuildContext c)=>RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(14),children:[const Text('گزارش‌های مالی',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),...{'مجموع فروش فاکتورها':'sales','دریافت‌ها':'income','هزینه‌ها':'expense','مانده فاکتورها':'due','ارزش خرید موجودی':'stock'}.entries.map((e)=>Card(child:ListTile(title:Text(e.key),trailing:Text('${money(v[e.value]??0)} تومان',style:const TextStyle(color:blue,fontWeight:FontWeight.bold))))),const Card(child:Padding(padding:EdgeInsets.all(12),child:Text('این گزارش‌ها خلاصه مدیریتی هستند و جایگزین دفاتر حسابداری رسمی یا اظهارنامه مالیاتی نیستند.')))]));}
